export function findSection(slug: string): DocSection | undefined {
  return DOC_SECTIONS.find((s) => s.slug === slug);
}

export function findDoc(
  section: string,
  slug: string
): { section: DocSection; page: DocPage } | undefined {
  const found = findSection(section);
  const page = found?.pages.find((p) => p.slug === slug);
  return found && page ? { section: found, page } : undefined;
}

/** Every doc in reading order, for prev/next and for handing Orion the list. */
export const DOC_PAGES: readonly (DocPage & { section: DocSection })[] =
  DOC_SECTIONS.flatMap((section) =>
    section.pages.map((page) => ({ ...page, section }))
  );

export function docHref(section: string, slug: string): string {
  return `/docs/${section}/${slug}`;
}
